 ctx.fillStyle='#20281f';ctx.fillRect(80,80,world.w-160,world.h-160);ctx.strokeStyle='#323b30';ctx.lineWidth=2;ctx.strokeRect(80,80,world.w-160,world.h-160);
 // Worn central safe-zone paint.
 ctx.save();ctx.translate(world.w/2,world.h/2);ctx.strokeStyle='#89966a18';ctx.lineWidth=3;ctx.setLineDash([18,22]);ctx.beginPath();ctx.arc(0,0,210,0,Math.PI*2);ctx.stroke();ctx.restore();
 for(const d of decor){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.rot);if(d.type==='grass'){ctx.strokeStyle='#66734d';ctx.globalAlpha=.55;ctx.lineWidth=2;for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(0,4);ctx.lineTo(rand(-9,9),-rand(4,d.r/2));ctx.stroke()}}else{ctx.fillStyle='#384034';ctx.globalAlpha=.75;ctx.fillRect(-d.r/2,-3,d.r,6);ctx.fillStyle='#69705a';ctx.fillRect(-d.r/3,-2,4,2)}ctx.restore()}
}
function drawObstacle(o){ctx.save();ctx.translate(o.x,o.y);ctx.rotate(o.rot);if(o.type==='car'){
 ctx.fillStyle='#0c100d77';ctx.beginPath();ctx.ellipse(2,7,o.w*.53,o.h*.62,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#252c26';ctx.fillRect(-o.w/2,-o.h/2,o.w,o.h);
 ctx.fillStyle='#697064';ctx.fillRect(-o.w/2+8,-o.h/2+2,o.w-16,o.h-4);
 ctx.fillStyle='#29322e';ctx.fillRect(-o.w*.21,-o.h*.37,o.w*.43,o.h*.74);
 ctx.fillStyle='#83908a';ctx.fillRect(-o.w*.18,-o.h*.31,o.w*.35,o.h*.2);ctx.fillRect(-o.w*.18,o.h*.12,o.w*.35,o.h*.2);
 ctx.fillStyle='#f0bd67';ctx.fillRect(-o.w/2+2,-o.h/2+5,4,6);ctx.fillRect(-o.w/2+2,o.h/2-11,4,6);ctx.fillStyle='#854438';ctx.fillRect(o.w/2-6,-o.h/2+5,4,6);ctx.fillRect(o.w/2-6,o.h/2-11,4,6);
 ctx.fillStyle='#101410';ctx.fillRect(-o.w/3,-o.h/2-2,o.w/5,4);ctx.fillRect(o.w/6,-o.h/2-2,o.w/5,4);ctx.fillRect(-o.w/3,o.h/2-2,o.w/5,4);ctx.fillRect(o.w/6,o.h/2-2,o.w/5,4);
 }else{ctx.fillStyle='#343b30';ctx.fillRect(-o.w/2,-o.h/2,o.w,o.h);ctx.fillStyle='#62664f';ctx.fillRect(-o.w/2+4,-o.h/2+4,o.w-8,o.h-8);ctx.strokeStyle='#343b30';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-o.w/2+6,0);ctx.lineTo(o.w/2-6,0);ctx.stroke()}ctx.restore()}
function drawZombie(z){ctx.save();ctx.translate(z.x,z.y);ctx.rotate(z.angle);let bob=Math.sin(z.phase)*1.5;ctx.translate(0,bob);ctx.fillStyle='#0b100d99';ctx.beginPath();ctx.ellipse(0,6,z.r*1.25,z.r*.72,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=z.hit?'#d78569':z.brute?'#75574a':'#73805c';ctx.beginPath();ctx.ellipse(0,0,z.r*1.05,z.r*.84,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=z.brute?'#806257':'#89936d';ctx.beginPath();ctx.arc(z.r*.55,-z.r*.36,z.r*.55,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d2ad71';ctx.fillRect(z.r*.72,-z.r*.53,2,2);ctx.fillRect(z.r*.72,-z.r*.2,2,2);ctx.strokeStyle='#b84538';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(z.r*.35,z.r*.02);ctx.lineTo(z.r*.77,z.r*.08);ctx.stroke();ctx.strokeStyle=z.brute?'#806257':'#73805c';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-2,-z.r*.55);ctx.lineTo(z.r*.65,-z.r*.65);ctx.moveTo(-2,z.r*.55);ctx.lineTo(z.r*.65,z.r*.62);ctx.stroke();if(z.brute){ctx.fillStyle='#d27b58';ctx.fillRect(-z.r,-z.r-7,z.r*2,3);ctx.fillStyle='#d27b58';ctx.fillRect(-z.r,-z.r-7,z.r*2*(z.hp/z.maxHp),3)}ctx.restore()}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.angle);if(player.invuln>0&&Math.floor(performance.now()/70)%2===0)ctx.globalAlpha=.5;ctx.fillStyle='#080d0a99';ctx.beginPath();ctx.ellipse(0,7,17,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c6d0ad';ctx.beginPath();ctx.arc(0,0,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='#4b5c45';ctx.beginPath();ctx.arc(-2,1,7.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e3d8b8';ctx.beginPath();ctx.arc(5,-5,4.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d9e3bd';ctx.fillRect(3,-4,13,5);ctx.fillStyle='#33392d';ctx.fillRect(8,-5,14,4);ctx.fillStyle='#d0b779';ctx.fillRect(19,-4,5,2);ctx.restore()}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.fillStyle='#111711';ctx.fillRect(0,0,W,H);let ox=Math.round(W/2-cam.x+(shake?rand(-shake,shake):0)),oy=Math.round(H/2-cam.y+(shake?rand(-shake,shake):0));ctx.save();ctx.translate(ox,oy);drawGround();for(const o of obstacles)drawObstacle(o);
 for(const p of pickups){ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=.72+.28*Math.sin(performance.now()/150);ctx.shadowBlur=15;ctx.shadowColor=p.type==='med'?'#9ee078':'#eec764';ctx.fillStyle=p.type==='med'?'#a6d77c':'#efc96e';ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#263021';if(p.type==='med'){ctx.fillRect(-1.5,-5,3,10);ctx.fillRect(-5,-1.5,10,3)}else{ctx.fillRect(-4,-3,8,6);ctx.fillStyle='#d8d1ad';ctx.fillRect(-2,-2,4,4)}ctx.restore()}
 for(const b of bullets){ctx.strokeStyle='#ffe2a0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(b.x-b.vx*.025,b.y-b.vy*.025);ctx.lineTo(b.x,b.y);ctx.stroke()}
 for(const z of zombies)drawZombie(z);if(player)drawPlayer();for(const p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.restore();
 // Edge vignette and faint focus reticle.
 let grad=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.22,W/2,H/2,Math.max(W,H)*.72);grad.addColorStop(0,'#00000000');grad.addColorStop(1,'#060907b8');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
 if(gameState==='playing'&&W>700){ctx.strokeStyle='#d8e1c277';ctx.lineWidth=1;ctx.beginPath();ctx.arc(mouse.x,mouse.y,8,0,Math.PI*2);ctx.moveTo(mouse.x-13,mouse.y);ctx.lineTo(mouse.x-5,mouse.y);ctx.moveTo(mouse.x+5,mouse.y);ctx.lineTo(mouse.x+13,mouse.y);ctx.moveTo(mouse.x,mouse.y-13);ctx.lineTo(mouse.x,mouse.y-5);ctx.moveTo(mouse.x,mouse.y+5);ctx.lineTo(mouse.x,mouse.y+13);ctx.stroke()}
}
function frame(now){let dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if(k==='r')beginReload();if(k===' '){e.preventDefault();if(gameState==='title'||gameState==='over')start()}});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){mouse.down=true;mouse.x=e.clientX;mouse.y=e.clientY}});addEventListener('pointerup',e=>{if(e.pointerType==='mouse')mouse.down=false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
const stick=$('stick'),knob=$('knob');let stickId=null;stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(stickId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.min(36,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);touchMove.x=Math.cos(a)*m/36;touchMove.y=Math.sin(a)*m/36;knob.style.transform=`translate(${Math.cos(a)*m}px,${Math.sin(a)*m}px)`}function endStick(e){if(e.pointerId===stickId){stickId=null;touchMove={x:0,y:0};knob.style.transform='translate(0,0)'}}stick.addEventListener('pointerup',endStick);stick.addEventListener('pointercancel',endStick);
const fire=$('fireBtn');fire.addEventListener('pointerdown',e=>{e.preventDefault();touchFire=true;fire.setPointerCapture(e.pointerId)});fire.addEventListener('pointerup',()=>touchFire=false);fire.addEventListener('pointercancel',()=>touchFire=false);$('mobileReload').addEventListener('pointerdown',e=>{e.preventDefault();beginReload()});
// Keep the virtual controls out of the way on desktop.
if(matchMedia('(pointer:fine)').matches)$('mobile').style.display='none';addEventListener('resize',()=>{if(gameState==='playing')$('mobile').style.display=matchMedia('(pointer:fine)').matches?'none':'block'});
})();
</script>
</body>
